mapper.select:
SELECT
    id, biz_section, category_id, parent_id, type, sub_type, sort,
    difficulty, content, options, answer, score, analysis, year, source,
    status, import_batch_id, reviewer_id, review_remark, reviewed_at,
    created_at, updated_at
FROM t_question
WHERE deleted = 0

    AND biz_section = #{q.bizSection}


    AND category_id = #{q.categoryId}


    AND type = #{q.type}


    AND difficulty = #{q.difficulty}


    AND parent_id = #{q.parentId}


    AND parent_id = 0


    AND year = #{q.year}


    AND status = #{q.status}


    AND import_batch_id = #{q.importBatchId}


    AND content LIKE CONCAT('%', #{q.keyword}, '%')

ORDER BY parent_id ASC, sort ASC, id ASC
